package dev.pocketengine.browser;

import java.io.File;
import java.nio.file.Files;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

public final class BrowserOwnerHistoryTest {
    private static File file()throws Exception{return new File(Files.createTempDirectory("browser-owner-history-").toFile(),"profiles.json");}
    @Test public void nativeHistorySurvivesNewRegistryButNeverRestoresLiveSessionOrGrant()throws Exception {File file=file();BrowserProfileRegistry registry=new BrowserProfileRegistry(file);BrowserProfileRegistry.Session old=registry.openSession(false);JSONObject row=registry.visitForOwner(old,"https://example.com/article?token=private#part","https://example.com/article?token=private#part",10,false);registry.bookmarkForOwner(old,row.getString("id"));BrowserProfileRegistry cold=new BrowserProfileRegistry(file);BrowserProfileRegistry.Session fresh=cold.openSession(false);JSONArray history=cold.historyForOwner(fresh);assertEquals(1,history.length());assertEquals("https://example.com/article",history.getJSONObject(0).getString("url"));assertTrue(history.getJSONObject(0).getBoolean("urlQueryOmitted"));assertTrue(history.getJSONObject(0).getBoolean("bookmark"));assertNotEquals(old.sessionId,fresh.sessionId);assertFalse(Files.readString(file.toPath()).contains("token=private"));assertFalse(history.toString().contains("approval"));}
    @Test public void switchingProfilesRejectsOldDialogActionsAndDoesNotMixHistory()throws Exception {BrowserProfileRegistry registry=new BrowserProfileRegistry(file());BrowserProfileRegistry.Session a=registry.openSession(true);JSONObject row=registry.visitForOwner(a,"https://a.example/","A",1,false);String b=registry.create("B",registry.revision(),true).getString("id");registry.select(b,registry.revision(),true);BrowserProfileRegistry.Session current=registry.openSession(true);assertEquals(0,registry.historyForOwner(current).length());assertThrows(SecurityException.class,()->registry.historyItemForOwner(a,row.getString("id")));assertThrows(SecurityException.class,()->registry.clearHistoryForOwner(a,true));}
    @Test public void boundedRecentHistoryNeverEvictsBookmarksAndExactIdsDoNotRetarget()throws Exception {BrowserProfileRegistry registry=new BrowserProfileRegistry(file());BrowserProfileRegistry.Session s=registry.openSession(false);JSONObject saved=registry.visitForOwner(s,"https://example.com/saved","saved",1,false);registry.bookmarkForOwner(s,saved.getString("id"));for(int i=0;i<120;i++)registry.visitForOwner(s,"https://example.com/"+i,"row "+i,i+2,false);assertEquals(100,registry.historyForOwner(s).length());assertEquals(saved.getString("url"),registry.historyItemForOwner(s,saved.getString("id")).getString("url"));registry.clearHistoryForOwner(s,false);assertEquals(1,registry.historyForOwner(s).length());registry.clearHistoryForOwner(s,true);assertThrows(IllegalStateException.class,()->registry.historyItemForOwner(s,saved.getString("id")));}
    @Test public void unsupportedPageCannotAccidentallyBookmarkThePreviousHttpPage()throws Exception {BrowserProfileRegistry registry=new BrowserProfileRegistry(file());BrowserProfileRegistry.Session s=registry.openSession(false);JSONObject saved=registry.visitForOwner(s,"https://example.com/saved","saved",1,false);assertNull(registry.visitForOwner(s,"about:blank","blank",2,false));assertNull(registry.visitForOwner(s,"https://user:credential@example.com/","bad",3,false));assertFalse(registry.historyItemForOwner(s,saved.getString("id")).getBoolean("bookmark"));}
    @Test public void ownerCloseIsRecordedAndProfileDeletionRemovesHistoryNotSources()throws Exception {File file=file();BrowserProfileRegistry registry=new BrowserProfileRegistry(file);String id=registry.create("work",registry.revision(),true).getString("id");registry.select(id,registry.revision(),true);BrowserProfileRegistry.Session s=registry.openSession(true);JSONObject row=registry.visitForOwner(s,"https://example.com/a","a",1,true);assertTrue(row.getBoolean("closed"));registry.requestDelete(id,registry.revision(),true);assertFalse(Files.readString(file.toPath()).contains("https://example.com/a"));assertThrows(SecurityException.class,()->registry.historyForOwner(s));}
    @Test public void historyAndBookmarksRetainEscapedSlashAndDotPathAcrossColdRegistry()throws Exception {File file=file();BrowserProfileRegistry registry=new BrowserProfileRegistry(file);BrowserProfileRegistry.Session session=registry.openSession(false);String path="/item/a%2Fb/%2E/%2e%2E/keep%3Fpart";JSONObject row=registry.visitForOwner(session,"https://example.com"+path+"?token=omitted#part","encoded resource",1,false);assertEquals("https://example.com"+path,row.getString("url"));assertTrue(row.getBoolean("urlQueryOmitted"));registry.bookmarkForOwner(session,row.getString("id"));BrowserProfileRegistry cold=new BrowserProfileRegistry(file);JSONObject saved=cold.historyItemForOwner(cold.openSession(false),row.getString("id"));assertEquals(path,new java.net.URI(saved.getString("url")).getRawPath());assertTrue(saved.getBoolean("bookmark"));assertFalse(Files.readString(file.toPath()).contains("token=omitted"));}
    @Test public void failedSaveDoesNotReplaceCurrentHistoryWithClaimedSuccess()throws Exception {File file=file();BrowserProfileRegistry registry=new BrowserProfileRegistry(file);BrowserProfileRegistry.Session s=registry.openSession(false);registry.visitForOwner(s,"https://example.com/a","a",1,false);Files.delete(file.toPath());Files.createDirectory(file.toPath());Files.writeString(new File(file,"blocker").toPath(),"x");assertThrows(Exception.class,()->registry.visitForOwner(s,"https://example.com/b","b",2,false));assertEquals(1,registry.historyForOwner(s).length());assertEquals("https://example.com/a",registry.historyForOwner(s).getJSONObject(0).getString("url"));}
}
